CREATE TABLE control.approval_policies (id uuid PRIMARY KEY, tenant_id text NOT NULL, code text NOT NULL, version integer NOT NULL, state text NOT NULL DEFAULT 'ACTIVE', UNIQUE (tenant_id, code, version), CHECK (state IN ('DRAFT','ACTIVE','DISABLED')));
CREATE TABLE control.approval_requests (id uuid PRIMARY KEY, tenant_id text NOT NULL, source_type text NOT NULL, source_id uuid NOT NULL, policy_id uuid NOT NULL REFERENCES control.approval_policies(id), policy_version integer NOT NULL, requested_by uuid NOT NULL, state text NOT NULL DEFAULT 'PENDING', context jsonb NOT NULL DEFAULT '{}'::jsonb, version integer NOT NULL DEFAULT 1 CHECK (version > 0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (state IN ('PENDING','APPROVED','REJECTED','CHANGES_REQUESTED','EXPIRED','CANCELLED')));
CREATE TABLE control.approval_decisions (id uuid PRIMARY KEY, tenant_id text NOT NULL, request_id uuid NOT NULL REFERENCES control.approval_requests(id), actor_id uuid NOT NULL, decision text NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK (decision IN ('APPROVED','REJECTED','CHANGES_REQUESTED')));
CREATE INDEX approval_requests_lookup ON control.approval_requests(tenant_id, state, created_at DESC);
